  'about.bookshopLeadIn': "Créé par la même petite entreprise qui tient notre librairie :",
  "about.eyebrow": "À propos de Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — À propos",
  "about.founderHeading": "📖 À propos de la fondatrice",
  "about.founder.p1": "Bonjour, je suis Concepcion, la fondatrice de Luminous StockHaven.",
  "about.founder.p2": "Je ne viens pas d'une grande entreprise technologique et je ne travaille pas dans un bureau de multinationale. Je suis une petite commerçante, comme vous. Je gère cinq boutiques en ligne, spécialisées dans les livres et les accessoires artisanaux pour amoureux des livres.\nComme beaucoup de commerçants indépendants, j'ai atteint mes limites en essayant de gérer un inventaire réparti sur plusieurs lieux, de suivre les ISBN des éditeurs à côté de mes propres références artisanales et de traiter les commandes fournisseurs avec des tableurs maladroits. Quand j'ai cherché une application pour m'aider, j'en ai essayé six différentes. Chacune était soit totalement incomplète, soit incroyablement confuse, soit abusive — des centaines de dollars par mois pour des outils de base.",
  "about.founder.p3": "Frustrée par une industrie qui étrangle les créateurs indépendants, j'ai décidé de construire ma propre solution. J'ai créé Luminous StockHaven par nécessité, pour gérer mes propres commerces proprement, efficacement et en toute tranquillité d'esprit.",
  "about.founder.p4": "J'ai décidé d'ouvrir cette plateforme au public à un prix honnête et abordable, parce que chaque petit commerçant mérite des outils qui fonctionnent vraiment sans mettre ses revenus en danger. Nous sommes indépendants, farouchement protecteurs de notre communauté, et créés par une commerçante, pour les commerçants.",
  "notice.ariaLabel": "Avis de marque et de droits d’auteur",
  "notice.heading": "🛡️ Conçu pour les commerçants, sans prix pour les vautours des grandes entreprises",
  "notice.intro": "J'ai créé cette application parce que je gère 5 boutiques et que j'en avais assez de me faire arnaquer par des logiciels confus à plusieurs centaines de dollars. Cette application a été conçue pour protéger les artistes indépendants, les artisans, les libraires et les boutiques locales.",
  "notice.legalHeading": "AVIS LÉGAL AUX CONCURRENTS ET IMITATEURS :",
  "notice.legalBody": "Nous surveillons activement le marché. Toute tentative d’extraire les données de notre plateforme, de cloner nos processus exclusifs ou de porter atteinte à notre propriété intellectuelle entraînera une action en justice immédiate et déterminée.",
  "notice.acquisitionHeading": "AUX SOCIÉTÉS D’ACQUISITION ET COURTIERS :",
  "notice.acquisitionBody": "Ne m'envoyez pas d'e-mail. Ne me contactez pas en message privé. Ne me proposez pas une « sortie stratégique ». Vous pouvez m'offrir des milliers, des millions, des milliards ou des billions — la réponse est Non. Vous n'achèterez pas cette application pour ensuite augmenter les prix pour mes collègues commerçants. Tout e-mail d'acquisition non sollicité sera immédiatement marqué comme spam et votre domaine sera bloqué définitivement de notre plateforme. Épargnez-vous la peine.",
