  "plans.backToWelcome": "Retour à l'accueil",
  "plans.eyebrow": "Formules et fonctionnalités",
  "plans.title": "Comparer les formules StockHaven",
  "plans.intro": "Un seul compte, quelle que soit la formule choisie — Business couvre jusqu'à cinq entreprises. Les prix sont mensuels en dollars américains, et les nouveaux clients éligibles du site web peuvent bénéficier d'un essai de sept jours sur Essentials et Business. Passer d'un abonnement Essentials existant à Business ne redémarre pas l'essai et ne crée pas un autre essai gratuit. Les prix des formules du site web s'entendent avant les taxes applicables, le cas échéant. Le montant exact vous sera indiqué avant d'autoriser un abonnement.",
  "plans.availableAtLaunch": "Disponible au lancement mobile",
