  "plans.mobileIncludedNote": "Les deux formules du site web incluent le compagnon mobile, un abonné du site web ne paie donc jamais le tarif mensuel mobile en plus.",
  "plans.priceNote": "Essentials coûte 14,99 $/mois plus les taxes applicables, le cas échéant. Business coûte 29,99 $/mois plus les taxes applicables, le cas échéant. Toute taxe requise est déterminée lors du paiement auprès du fournisseur et doit figurer dans le total final avant le paiement. Cette page de comparaison n'est ni un devis fiscal ni une autorisation de paiement.",
  "plans.mobilePriceNote": "La formule mobile seule coûte 4,99 $/mois à son prix de base prévu aux États-Unis. L'App Store ou Google Play affiche le prix réel de l'abonnement local et les taxes applicables avant l'achat. Ses limites de produits, de sites et de personnel sont fixées au lancement, séparément des niveaux du site web.",
  "plans.planChangeNote": "Un changement de formule sur le site web doit être confirmé par le fournisseur de facturation. Le nouveau prix, la date d'effet et tout calcul au prorata seront expliqués avant l'autorisation du changement. Une mise à niveau ne doit pas créer un deuxième abonnement.",
  "plans.providerNote": "Les prix, les débits et les essais sont gérés par le fournisseur auprès duquel vous vous abonnez — l'App Store, Google Play, le site web ou Shopify — jamais par cette page.",
