  "upgrade.introTrial": " (essai).",
  "upgrade.introPeriod": ".",
  "upgrade.pastDueTitle": "Paiement en retard",
  "upgrade.pastDueBody": "Votre dernier paiement n'a pas abouti, cet abonnement est donc en retard. Vous gardez l'accès complet pendant 14 jours à partir du paiement échoué, le temps de le corriger. S'il n'est pas corrigé, l'abonnement est annulé, l'espace de travail devient en lecture seule pendant 15 jours, puis le compte et toutes ses informations sont supprimés. Payer à tout moment avant la suppression rétablit tout. Mettez à jour votre moyen de paiement ci-dessous. Si vous avez besoin d'aide, écrivez à",
