  "upgrade.downgradeWarning5": "L'inventaire lui-même passe sans difficulté à Essentials — rien de ce que vous avez stocké n'est supprimé.",
  "upgrade.dialogUpgradeDesc": "Votre essai et votre abonnement restent sur le même abonnement — pas de deuxième abonnement, pas de nouvel essai.",
