  "upgrade.reviewJoin1": ",",
  "upgrade.reviewJoin2": " et notre",
  "upgrade.reviewPeriod": ".",
  "upgrade.upgradeNeverRestartsTrial": "Passer à une formule supérieure ne redémarre jamais votre essai gratuit.",
  "upgrade.trialHistoryNote": "Si vous payez Essentials et passez à Business, vous conservez le même compte client et le même historique d'essai. Business n'inclut pas un essai supplémentaire de sept jours. Si vous passez à une formule supérieure alors que votre essai d'origine est toujours en cours, sa date de fin d'origine n'est pas réinitialisée.",
  "upgrade.providerConfirmNote": "Les changements de formule nécessitent une confirmation du fournisseur de facturation. Toute différence de prix, tout calcul au prorata et toute date d'effet doivent être affichés avant que vous approuviez le changement. Une mise à niveau ne doit pas créer un deuxième abonnement simultané.",
  "upgrade.chargedThroughProviderNote": "Les changements de formule sont facturés par l'intermédiaire du fournisseur de facturation. Vous pouvez annuler votre abonnement depuis cette page à l'aide du bouton Annuler l'abonnement sous votre formule actuelle, ou depuis les Paramètres. L'annulation arrête les renouvellements futurs à la fin de votre période payée ; elle ne met jamais fin à votre accès immédiatement. Les espaces de travail offerts existants ne sont pas facturés par la consultation de ces options.",
  "billing.cancel.title": "Annuler l'abonnement",
  "billing.cancel.description": "Se désabonner de {plan}. L'annulation arrête les renouvellements futurs à la fin de votre période payée — elle ne met jamais fin à votre accès immédiatement.",
  "billing.cancel.yourPlan": "votre formule",
  "billing.cancel.doneTitle": "Votre abonnement est annulé.",
  "billing.cancel.doneWithEnd": "Vous conservez un accès complet jusqu'au {endDate}. Après cette date, vous disposez d'un délai de grâce de {graceDays} jours en lecture seule — vous pouvez toujours vous connecter et voir vos produits, mais vous ne pouvez rien ajouter, modifier, supprimer, scanner, importer, exporter ni changer. {gracePart}",
  "billing.cancel.graceEndsOn": "Après la fin du délai de grâce de 15 jours le {date}, votre compte et toutes ses informations sont définitivement supprimés et ne peuvent pas être récupérés.",
  "billing.cancel.doneNoEnd": "Vous conservez un accès complet jusqu'à la fin de votre période payée. Après cela, un délai de grâce de 15 jours en lecture seule s'applique. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Vous avez annulé dans les 3 jours suivant votre premier débit payé, vous pourriez donc avoir droit à un remboursement de ce premier paiement. L'annulation ne déclenche pas elle-même le remboursement — demandez-le via {contact}.",
  "billing.cancel.refundWindowClosed": "L'annulation ne déclenche pas elle-même un remboursement. Les remboursements ne s'appliquent que dans les 3 jours suivant le premier débit payé réussi, sur demande via {contact}.",
  "billing.cancel.notCanceledTitle": "Votre abonnement n'a PAS été annulé.",
  "billing.cancel.contactCode": "Si vous contactez {contact}, mentionnez ce code : {code}",
  "billing.cancel.alreadyCanceledTitle": "Cet abonnement est déjà annulé.",
  "billing.cancel.alreadyCanceledWithEnd": "Il se termine le {date}. Vous conservez un accès complet jusque-là. Après cette date, vous disposez d'un délai de grâce de {graceDays} jours en lecture seule pour voir vos produits. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "Il se termine à la fin de la période payée en cours. Vous conservez un accès complet jusque-là.",
  "billing.cancel.appStoreNote": "Si vous vous abonnez un jour via Google Play ou l'Apple App Store, vous devrez peut-être l'annuler dans les paramètres d'abonnement de cette boutique. Cette boîte de dialogue ne peut pas arrêter la facturation d'une boutique d'applications. Désinstaller l'application ou supprimer votre compte StockHaven n'annule pas un abonnement d'une boutique.",
  "billing.cancel.trialNote": "Annuler pendant votre essai vous conserve vos 7 jours complets — l'accès se termine le {date}, et vous ne serez pas débité.",
  "billing.cancel.trialNoteNoDate": "Annuler pendant votre essai vous conserve vos 7 jours complets, et vous ne serez pas débité.",
  "billing.cancel.keepAccessUntil": "Vous conservez un accès complet jusqu'au {date}.",
  "billing.cancel.endOfPaidPeriod": "la fin de votre période payée",
  "billing.cancel.keepAccessRest": "L'annulation arrête uniquement les renouvellements futurs — elle ne met jamais fin à votre accès immédiatement, et aucun mois gratuit supplémentaire n'est ajouté.",
  "billing.cancel.gracePeriodTitle": "Après cette date, un délai de grâce de {graceDays} jours en lecture seule.",
  "billing.cancel.gracePeriodRest": "Vous pouvez toujours vous connecter et voir vos produits, pour regarder ce que vous aviez et le noter. Tout le reste est bloqué : pas d'ajout, de modification, de suppression, de scan, d'importation, d'exportation ou de migration, pas de paramètres, pas de personnel.",
