  "exports.eyebrow": "Données",
  "exports.title": "Exportations et sauvegardes",
  "exports.subtitleStart": "Les téléchargements sont toujours limités à",
  "exports.subtitleRest": ". Chaque fichier est étiqueté avec le nom de l'entreprise et la date de sa création.",
  "exports.createBusinessFirst": "Créez d'abord une entreprise — les exportations appartiennent à une entreprise, pas à l'application.",
  "exports.lockedTitle": "Les exportations CSV et Excel sont une fonctionnalité Business",
  "exports.lockedDesc": "Votre espace de travail est sur la formule Essentials. Business ajoute les exportations CSV et Excel, la valorisation du stock, des produits et du personnel illimités, les fournisseurs, les achats et les lots.",
  "exports.seeBusiness": "Voir ce que Business inclut",
  "exports.whatTheseAre": "Ce que sont ces fichiers",
  "exports.about1": "Chaque ensemble de données est disponible en CSV ou en véritable classeur Excel (.xlsx) — le classeur d'inventaire complet est réservé à Excel, avec une feuille par ensemble de données. Les fichiers CSV s'ouvrent dans Excel, Numbers, Google Sheets et la plupart des applications de stock. Le texte UTF-8, les virgules entre guillemets, les sauts de ligne dans les remarques et les zéros initiaux des codes sont tous préservés, et les cellules qui commencent comme une formule sont neutralisées pour qu'un tableur les ouvre comme du texte.",
  "exports.about2": "Dans les fichiers Excel, les SKU, UPC, ISBN et codes-barres sont des cellules de texte — jamais en notation scientifique et jamais de zéros coupés — avec des largeurs de colonne, des filtres d'en-tête et des formats de devise ou de quantité appliqués. Le classeur d'inventaire complet conserve les produits, les niveaux de stock, les emplacements et les mouvements sur des feuilles séparées.",
  "exports.about3": "Les très grandes exportations s'arrêtent à 20 000 lignes par ensemble de données — dans ce cas, le nom du fichier l'indique (truncated-20000), pour qu'un fichier partiel ne passe jamais pour complet.",
  "exports.about4": "Une sauvegarde est un instantané de vos données, pas une restauration en un clic. La restaurer est un travail manuel, avec vérification préalable, conservez donc le fichier en lieu sûr — rien dans l'application ne peut encore recréer une entreprise supprimée à partir de celui-ci. Le code de l'application et les sauvegardes de la plateforme Base44 sont gérés séparément de ces fichiers.",
  "exports.about5": "Les photos et pièces jointes sont listées sous forme de liens stockés — les fichiers d'images eux-mêmes ne sont pas inclus dans le téléchargement.",
  "exports.backupTitle": "Sauvegarde complète",
  "exports.backupDesc": "Un fichier contenant les produits, emplacements, niveaux de stock, journal complet des mouvements, fournisseurs, achats, commandes, retours, comptages et annonces de cette entreprise — plus les paramètres de son profil. Conservez-le dans un endroit que vous contrôlez.",
  "exports.backupIncludes1": "Produits, codes, coûts et remarques",
  "exports.backupIncludes2": "Emplacements et quantités par emplacement",
  "exports.backupIncludes3": "Chaque mouvement, avec l'auteur et l'heure",
  "exports.backupIncludes4": "Achats, commandes, retours et comptages",
  "exports.buildingBackup": "Création de la sauvegarde…",
  "exports.backupJson": "Sauvegarde (JSON)",
  "exports.excelSnapshot": "Instantané Excel",
