  "import.eyebrow": "Données",
  "import.title": "Centre d'importation",
  "import.subtitleStart": "Trois opérations de tableur distinctes, pour qu'une correction de prix ne puisse jamais arriver comme une réception de stock. Tout aboutit dans",
  "import.subtitleRest": " uniquement, et rien n'est écrit tant qu'un essai à blanc n'a pas réussi.",
  "import.createBusinessFirst": "Créez d'abord une entreprise — les produits importés appartiennent à une entreprise.",
  "import.createBusinessFirstShort": "Créez d'abord une entreprise.",
  "import.whatEachDoes": "Ce que fait chaque opération",
  "import.createTitle": "Créer de nouveaux produits",
  "import.createDesc": "ajoute les lignes qui ne figurent pas encore dans le catalogue. Les SKU et codes-barres en double déjà utilisés sont ignorés, et le stock d'ouverture peut aboutir dans un emplacement de votre choix sous forme de réception.",
  "import.updateTitle": "Mettre à jour des produits existants",
  "import.updateDesc": "fait correspondre chaque ligne par SKU ou ID d'enregistrement et affiche l'ancienne valeur à côté de la nouvelle proposée. Les cellules vides laissent la valeur enregistrée telle quelle, sauf si vous demandez l'effacement des blancs, et les quantités ne sont jamais modifiées.",
  "import.receiveModeTitle": "Réceptionner du stock",
  "import.receiveModeDesc": "ajoute les quantités arrivées à un emplacement et écrit une réception dans le journal des mouvements pour chaque ligne. Chaque lot est marqué, de sorte que la même feuille ne peut pas être réceptionnée deux fois.",
  "import.excelNote": "Les classeurs Excel (.xlsx) sont lus directement — choisissez la feuille de calcul et les colonnes sont associées pour vous. Les codes restent entiers : un UPC enregistré comme texte conserve ses chiffres et ses zéros initiaux. Les lignes qui ne peuvent pas être importées sont listées avec un motif",
  "import.excelNoteDownload": " et peuvent être téléchargées sous forme de fichier.",
  "import.excelNoteFix": ", pour que vous puissiez les corriger et réessayer.",
  "import.matchColumns": "Associer les colonnes",
  "import.columnFallback": "Colonne {column}",
  "import.ignoreColumn": "Ignorer cette colonne",
  "import.mapNameRequired": "Associez une colonne au nom du produit — chaque ligne importée a besoin d'un nom.",
  "import.receiveMissingMessage": "Associez une colonne au SKU ou à l'ID d'enregistrement, et une autre à la quantité reçue.",
  "import.updateMissingMessage": "Associez une colonne au SKU ou à l'ID d'enregistrement — chaque ligne est trouvée par l'un d'eux.",
  "import.dryRunTitle": "Essai à blanc",
  "import.dryRunIntro": "Lancez un essai à blanc pour tester chaque ligne par rapport au catalogue. Il n'enregistre rien.",
  "import.dryRunStale": "La configuration a changé depuis l'essai à blanc",
  "import.dryRunPassed": "Essai à blanc réussi",
  "import.dryRunReadyWords": "lignes seraient créées",
  "import.dryRunSkipped": "ignorées",
  "import.dryRunRoom": "Vous avez {have} produits. Votre forfait en admet {cap}, donc {room} de plus peuvent entrer.",
  "import.draftTooLarge": "Ce fichier est trop gros pour être gardé sur cet appareil. Si vous partez, vous devrez choisir le fichier à nouveau.",
  "import.dryRunOver": "{count} lignes ne tiendraient pas — votre forfait est plein.",
  "import.notImportedPlanFull": "{count} lignes n’ont pas été importées — votre forfait est plein.",
  "import.dryRunOpeningUnits": "unités d'ouverture",
  "import.dryRunUnitsNoLocation": "Le fichier contient {units} unités de stock d'ouverture, mais aucun emplacement de stock n'est choisi — alors aucune de ces unités ne sera ajoutée. Choisissez ci-dessus où vit le stock d'ouverture, sinon les produits arriveront avec zéro compté.",
  "import.quantityNeedsMatch": "Votre fichier comporte une colonne de quantité — « {column} » — qui n'est pas associée à Quantité de stock d'ouverture. Associez-la ci-dessus, ou définissez cette colonne sur Ignorer cette colonne, avant que la vérification puisse s'exécuter — sinon vos produits seraient créés sans qu'aucun de leur stock soit compté.",
