  "reports.movementsCapped": "Seules les {cap} écritures les plus récentes du journal ont été lues, les mouvements plus anciens ne figurent donc pas dans les totaux. Réduisez la période pour voir des chiffres exacts sur une fenêtre.",
  "reports.footnote": "Les ventes utilisent le prix de vente actuel de chaque produit, les réceptions utilisent le coût enregistré à l'arrivée du stock, et les pertes utilisent le coût unitaire actuel. L'argent manquant n'est jamais considéré comme zéro — laissez un champ vide tant que le chiffre n'est pas connu. Un rapport est une vue, pas un document : rien n'est écrit dans vos relevés quand vous en lancez un.",
