  "print.clearSelection": "Effacer la sélection",
  "print.templateIsBusiness": "{label} est une fonctionnalité Business",
  "print.supplierBlockedDesc": "Les documents fournisseurs vont avec la formule Business — fournisseurs, achats et bons de commande. Tout ce que vous avez maintenant continue de fonctionner.",
  "print.seeBusiness": "Voir ce que Business inclut",
  "print.nothingToPrint": "Rien à imprimer pour l'instant",
  "print.pickOrderHint": "Choisissez un bon de commande dans la liste pour prévisualiser le document.",
  "print.pickCustomerOrderHint": "Choisissez une commande client dans la liste pour prévisualiser le document.",
  "print.pickReturnHint": "Choisissez un retour enregistré dans la liste pour prévisualiser le document.",
  "print.chooseStyleHint": "Choisissez un style, puis sélectionnez des produits dans la liste. L'aperçu montre exactement ce qui sort de l'imprimante.",
  "print.howToReach": "Comment joindre votre imprimante",
  "print.howIntro": "Cette application se connecte aux imprimantes que vous possédez déjà — ce n'est pas une imprimante elle-même. Il existe quatre façons d'en joindre une, et les étiquettes s'impriment sur les deux formules par n'importe laquelle d'entre elles. Les bordereaux d'emballage, bons de commande, documents fournisseurs et rapports sont réservés à Business, quelle que soit la connexion.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Depuis cette page, sur Chrome ou Edge sur ordinateur et sur Chrome sur Android : choisissez votre imprimante d'étiquettes et les étiquettes partent directement vers elle. Cela ne fonctionne pas dans Safari sur iOS — sur un iPhone, l'impression Bluetooth arrive avec l'application mobile à la place. Une imprimante qui ne parle que le ZPL de Zebra ou le langage propre à Brother ne comprendra pas les étiquettes envoyées par cette page ; cela est vérifié sur de vraies imprimantes avant d'être déclaré fonctionnel.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Installez l'imprimante sur le Wi-Fi de votre boutique, puis utilisez le bouton Imprimer — l'impression passe par l'imprimante installée sur cet ordinateur, via le réseau de la boutique. Sur un iPhone, AirPrint est intégré : une imprimante AirPrint sur le même Wi-Fi apparaît simplement dans la feuille d'impression, sans cordon ni application, et l'application n'a besoin d'aucun code spécifique à AirPrint. L'imprimante doit prendre en charge AirPrint (la plupart des nouvelles le font) et le téléphone et l'imprimante doivent être sur le même Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Branchez l'imprimante au réseau de votre boutique avec un cordon Ethernet, installez-la sur l'ordinateur, et imprimez via le bouton Imprimer. Ethernet est un chemin pour ordinateurs — les iPhones n'utilisent pas de cordons Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Branchez l'imprimante à l'ordinateur avec son cordon et utilisez le bouton Imprimer — l'impression passe par l'imprimante installée sur place. Sur un téléphone Android avec un câble USB OTG, le bouton USB ci-dessus parle directement à l'imprimante. Les iPhones ne peuvent pas imprimer directement en USB — pas de WebUSB là-bas — utilisez donc le Wi-Fi / AirPrint, ou le Bluetooth depuis l'application mobile.",
  "print.howCordsLead": "Les cordons servent toujours aux iPhones, à une étape près.",
  "print.howCordsBody": "Une imprimante USB branchée à l'ordinateur de la boutique, ou une imprimante Ethernet câblée au réseau, apparaît sur votre iPhone via le Wi-Fi de la boutique (AirPrint / imprimante partagée) — les cordons mettent solidement l'imprimante sur le réseau, et le téléphone l'atteint sans fil.",
  "print.howOfflineLead": "Si internet tombe,",
  "print.howOfflineBody": "les étiquettes et documents déjà sur cette page s'impriment toujours — le bouton Imprimer, le PDF des étiquettes, le Bluetooth et l'USB n'ont besoin d'aucune connexion. Ce qui a besoin d'internet, c'est de charger la page et ses produits au départ. Le mode hors ligne complet (travailler dans l'application sans aucune connexion) est une construction distincte, plus importante, et n'est pas revendiqué ici.",
