  "settings.cancelSubscription": "Annuler l'abonnement",
  "settings.cancelTerms.appleLink": "Instructions d'annulation Apple",
  "settings.cancelTerms.googlePlayLink": "Instructions d'annulation Google Play",
  "settings.cancelTerms.graceTitle": "Après la fin de votre période payée — délai de grâce de 15 jours, puis suppression :",
  "settings.cancelTerms.intro": "Voici les conditions des abonnements payants de Luminous StockHaven. La facturation des abonnements du site web passe par Stripe. Vous pouvez annuler vous-même votre abonnement à tout moment à l'aide du bouton Annuler l'abonnement ci-dessous — aucune approbation du personnel n'est nécessaire. Les demandes d'annulation et de remboursement peuvent également être traitées via le contact officiel de l'assistance client, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Vous pouvez annuler vous-même votre abonnement à tout moment. Aucune approbation du personnel n'est requise. Les renouvellements futurs ne s'arrêtent qu'après confirmation de l'annulation par le fournisseur de facturation.",
  "settings.cancelTerms.noApprovalTitle": "Annuler sans approbation :",
  "settings.cancelTerms.paymentBody": "Pour les essais payants, l'essai de sept jours nécessite un moyen de paiement à l'inscription. Sauf annulation avant le délai d'annulation de l'essai applicable, la formule mensuelle choisie sera débitée automatiquement après l'essai. Le prix, la première date de facturation et le délai d'annulation propre au fournisseur doivent être affichés lors de l'inscription. La facturation de l'essai passe par Stripe.",
  "settings.cancelTerms.paymentTitle": "Moyen de paiement et renouvellement automatique :",
  "settings.cancelTerms.remainingBody": "Si vous avez déjà payé une période de facturation, vous pouvez conserver l'accès jusqu'à cette date de fin de période payée vérifiée. Une résiliation anticipée nécessite une confirmation appropriée du fournisseur et tout traitement de remboursement applicable. L'accès à l'essai gratuit se termine selon la date de fin d'essai confirmée par le fournisseur.",
  "settings.cancelTerms.remainingTitle": "Accès restant :",
  "settings.cancelTerms.storesBody": "Si vous vous abonnez un jour via Google Play ou l'Apple App Store, votre abonnement est facturé et géré par cette boutique. Vous devrez peut-être l'annuler directement dans la section des abonnements du même compte Google ou Apple utilisé pour vous abonner. Annuler un abonnement distinct du site web, désinstaller cette application ou demander la suppression de votre compte Luminous StockHaven n'annule pas automatiquement un abonnement facturé par une boutique. Vérifiez votre reçu d'achat pour confirmer qui vous facture.",
  "settings.cancelTerms.storesTitle": "Abonnements Google Play et Apple App Store (si vous vous abonnez un jour via une boutique) :",
  "settings.cancelTerms.title": "Conditions d'annulation",
  "settings.cancelTerms.trialBody": "L'essai de sept jours ne peut être utilisé qu'une seule fois par client éligible. Annuler un essai ou un abonnement ne donne pas droit à un autre essai ; les clients de retour doivent choisir un abonnement payant.",
  "settings.cancelTerms.trialTitle": "Un seul essai gratuit :",
  "settings.canceled.endsOn": "Cet abonnement est annulé et se termine le {date}. Vous conservez un accès complet jusque-là.",
  "settings.delete.checking": "Vérification d'une demande de suppression existante…",
  "settings.delete.description": "Demander la suppression de votre compte de connexion Luminous StockHaven.",
  "settings.delete.dialogDescription": "Ceci demande un examen de la suppression du compte. Cela ne supprime pas immédiatement votre identifiant ni votre inventaire, et n'annule aucun abonnement Stripe. Saisissez {word} pour confirmer que vous souhaitez soumettre la demande.",
  "settings.delete.dialogTitle": "Demander la suppression du compte",
  "settings.delete.enterDelete": "Saisissez {word} pour confirmer",
  "settings.delete.exportFirst": "Exportez d'abord votre inventaire si vous devez conserver vos relevés.",
  "settings.delete.intro": "Soumettre une demande ne supprime pas immédiatement votre compte, vos entreprises ou votre inventaire. Les demandes sont examinées séparément avant que la suppression puisse être effectuée. Cette demande n'annule pas un abonnement Stripe et n'arrête pas la facturation future ; l'annulation de l'abonnement doit être traitée séparément via le fournisseur de facturation.",
