  'settings.details.taxRateHint': 'Définissez-le une fois. Chaque nouvelle commande de vente remplit sa propre taxe à partir de ce taux — vous pouvez toujours modifier la taxe sur une commande précise.',
  "settings.details.taxMode": "Comment les commandes reçoivent leur taxe",
