  "settings.details.taxModeHint": "Le mode fixe utilise votre taux pour chaque nouvelle commande. Le mode automatique remplit la taxe d'une nouvelle commande avec le taux de base de l'État du client dès que l'État figure sur la commande, et la remplit de nouveau si l'État change. Ce sont des taux de base d'État — les taxes locales peuvent s'ajouter. Une commande sans État, ou hors des États-Unis, utilise votre taux fixe ci-dessus.",
  'settings.details.gs1Prefix': "Préfixe d’entreprise GS1",
  'settings.details.gs1PrefixHint': "Seulement si vous détenez une licence de préfixe auprès de GS1. Indiquez-le une fois et le générateur de codes du formulaire produit pourra créer de vrais codes UPC et EAN commerciaux à partir de vos propres numéros — chacun utilisé une seule fois et jamais réutilisé. Laissez vide si vous n’en avez pas; l’application n’invente jamais de préfixe.",
