  "settings.trial.cancelKeeps": "Annuler pendant votre essai vous conserve vos 7 jours complets — l'accès se termine le {date}, et vous ne serez pas débité.",
  "staff.access.noSeatBody": "Votre compte n'a pas de siège de personnel pour cette entreprise, son stock reste donc fermé. Demandez au propriétaire de vous ajouter dans Personnel et rôles.",
  "staff.access.noSeatTitle": "Cette entreprise n'est pas ouverte à votre identifiant",
  "staff.access.pendingBody": "Cette entreprise a une invitation pour votre e-mail qui n'a pas été activée. Demandez au propriétaire de définir votre statut de personnel sur actif. Rien n'est visible ici jusque-là.",
  "staff.access.pendingTitle": "Votre invitation n'est pas encore active",
  "staff.access.signOut": "Se déconnecter",
  "staff.access.suspendedBody": "Un administrateur a suspendu ce compte de personnel pour l'entreprise active. Demandez-lui de vous remettre sur actif, puis reconnectez-vous.",
  "staff.access.suspendedTitle": "Votre accès est en pause",
  "staff.addFirst": "Ajouter le premier membre du personnel",
  "staff.addMember": "Ajouter un membre du personnel",
  "staff.emptyBody": "Ajoutez une personne, donnez-lui un rôle et les autorisations qui l'accompagnent, et elle est invitée par e-mail à se connecter à cette entreprise.",
  "staff.emptyTitle": "Aucun personnel pour l'instant",
  "staff.eyebrow": "Équipe",
  "staff.how.p1": "Chaque membre a un rôle et sa propre liste d'autorisations, vous pouvez donc partir d'un rôle et modifier une chose sans créer un nouveau rôle. Modifier un rôle ne réécrit pas les membres qui y sont déjà — ouvrez un membre pour réappliquer les valeurs par défaut de son rôle.",
  "staff.how.p2": "Les rôles personnalisés sont une fonctionnalité Business : Essentials utilise les cinq rôles intégrés (Propriétaire, Responsable, Employé de stock, Vendeur, Observateur).",
  "staff.how.p3": "Les invitations sont envoyées par e-mail. Un membre ne peut se connecter qu'une fois qu'il a accepté, et retirer quelqu'un de cette liste ne supprime pas son compte dans l'application.",
  "staff.how.p4": "Une boutique est l'emplacement auquel une personne est affectée. Elle est enregistrée sur sa fiche ; ce qu'elle peut ouvrir reste décidé par son rôle et ses autorisations.",
  "staff.how.p5": "Les autorisations décident ce que chaque personne peut ouvrir : les éléments de menu hors de son rôle sont masqués, et une adresse bloquée affiche un avis « pas dans votre rôle » au lieu de la page. Une modification s'applique la prochaine fois que cette personne charge l'application ; suspendre un membre le bloque entièrement.",
  "staff.how.p6": "Les administrateurs peuvent voir et modifier toutes les données, gérer les utilisateurs et les rôles de l'application, et ne sont jamais limités par un rôle de personnel. Quelqu'un sans fiche de personnel — le propriétaire d'une nouvelle entreprise — conserve un accès complet.",
