  "payroll.dd.help": "Recueillez les coordonnées bancaires de chaque membre de l'équipe en toute sécurité. Les informations transmises vont au propriétaire uniquement — personne d'autre ne peut les voir.",
  "payroll.dd.invite": "Envoyer la demande",
