  "payroll.dd.savings": "Épargne",
  "payroll.dd.steps.body": "1. Vous avez besoin d'un compte bancaire professionnel capable d'envoyer des paiements ACH. 2. Recueillez un formulaire d'autorisation signé auprès de chaque membre de l'équipe — un chèque annulé aide à vérifier les numéros. 3. Envoyez la paie 2 à 3 jours ouvrables avant le jour de paie pour que l'argent arrive à temps. 4. La plupart des États exigent le consentement écrit du membre de l'équipe. Cette application recueille les formulaires et vous guide étape par étape — l'envoi effectif de l'argent se fait par votre propre banque.",
