  "auth.sameEmailNotice": "Vous avez déjà notre application depuis Google Play ou l'App Store ? Utilisez le même e-mail ici — celui avec lequel vous vous connectez à l'application — pour que votre boutique et votre inventaire vous suivent. Un e-mail différent démarre une boutique totalement nouvelle et vide.",
