  "recovery.changeIntro": "Vous êtes entré — pour une seule étape : choisissez le nouvel e-mail de votre compte. Votre boutique, votre inventaire et l'accès de votre équipe le suivent.",
  "recovery.doneBody": "L'e-mail de votre compte est changé et cette connexion est de nouveau votre connexion habituelle. Bon retour.",
