  "rewards.void": "Annuler",
  "rewards.voided": "Récompense annulée.",
  "workforce.tab.rewards": "Récompenses",
  "training.lessons.mgr-give-rewards.step1": "Ouvrez Équipe et touchez Récompenses. Choisissez le membre de l'équipe, puis le type : un pourcentage de réduction en boutique, une carte cadeau, ou autre chose que vous décrivez avec vos propres mots.",
  "training.lessons.mgr-give-rewards.step2": "Donnez à la récompense un nom court et une note si vous le souhaitez. La personne reçoit une cloche tout de suite, et la récompense l'attend dans ses Mes récompenses avec son propre code.",
  "training.lessons.mgr-give-rewards.step3": "La limite, par conception : vous récompensez le PERSONNEL uniquement. Vous ne pouvez pas vous récompenser vous-même ni un autre responsable — récompenser un responsable est la décision du propriétaire, et l'application le refusera clairement.",
  "training.lessons.mgr-give-rewards.step4": "À la caisse, saisissez le code que le membre de l'équipe vous montre et marquez-le comme utilisé — chaque code fonctionne une fois. Vous pouvez annuler une récompense que vous avez donnée si les plans changent ; les cadeaux du propriétaire appartiennent au propriétaire pour les annuler.",
  "training.lessons.mgr-give-rewards.title": "Donner des récompenses à votre personnel",
  "training.lessons.owner-give-rewards.step1": "Les récompenses vivent dans Personnel, sur l'onglet Récompenses, et elles sont réservées au forfait Business — sur Essentials, l'onglet Récompenses n'est tout simplement pas là, comme chaque partie de l'application réservée à Business.",
  "training.lessons.owner-give-rewards.step2": "Vous pouvez récompenser N'IMPORTE QUI dans l'équipe — personnel et responsables. Choisissez la personne, puis le type : un pourcentage de réduction en boutique (le pourcentage que vous choisissez), une carte cadeau valable partout, ou toute incitation que vous décrivez avec vos propres mots.",
  "training.lessons.owner-give-rewards.step3": "La récompense arrive avec son propre code à usage unique et fait sonner la cloche de la personne. Elle montre le code à la caisse ; un propriétaire ou un responsable le saisit pour le marquer comme utilisé.",
  "training.lessons.owner-give-rewards.step4": "Un bon de récompense imprimé ou partagé ne porte que le nom de VOTRE entreprise — jamais celui de l'application. C'est le merci de votre boutique, pas une publicité.",
  "training.lessons.owner-give-rewards.title": "Donner des récompenses (formule Business)",
  "training.lessons.owner-rewards-oversight.step1": "Votre responsable peut aussi donner des récompenses — au personnel uniquement. L'application refuse qu'un responsable se récompense lui-même ou récompense un autre responsable ; récompenser un responsable est toujours votre décision.",
  "training.lessons.owner-rewards-oversight.step2": "Vous voyez chaque récompense de l'entreprise dans l'Historique des récompenses : qui l'a donnée, qui l'a reçue, et si elle est prête, utilisée ou annulée. Un responsable ne voit que les récompenses qu'il a données et celles qu'il a reçues.",
  "training.lessons.owner-rewards-oversight.step3": "Vous pouvez annuler n'importe quelle récompense, y compris celle que votre responsable a donnée. Un responsable peut annuler ses propres cadeaux, mais jamais les vôtres.",
  "training.lessons.owner-rewards-oversight.step4": "Chaque code fonctionne exactement une fois, et une récompense annulée ne peut jamais être utilisée — l'historique montre toujours comment une récompense s'est terminée.",
  "training.lessons.owner-rewards-oversight.title": "Superviser les récompenses : les dons de votre responsable",
  "training.lessons.staff-your-rewards.step1": "Quand votre responsable ou le propriétaire vous donne une récompense, votre cloche sonne. Ouvrez Équipe et touchez Récompenses pour la voir sous Mes récompenses.",
  "training.lessons.staff-your-rewards.step2": "Chaque récompense a son propre code. Gardez-le pour vous — celui qui montre le code à la caisse est celui qui utilise la récompense.",
  "training.lessons.staff-your-rewards.step3": "Pour l'utiliser, montrez le code quand vous achetez. La personne à la caisse le saisit et le marque comme utilisé — chaque code fonctionne exactement une fois.",
  "training.lessons.staff-your-rewards.step4": "Les récompenses sont un avantage du forfait Business. Si votre boutique n'est pas sur Business, il n'y a aucun onglet Récompenses — c'est le forfait, pas une erreur.",
  "training.lessons.staff-your-rewards.title": "Vos récompenses : trouver votre code et l'utiliser",
  "training.module.rewards": "Récompenses et incitations",
