  "pos.events.heldPlanNote": "Certaines ventes ci-dessous sont arrivées pendant que cette boutique n'était pas sur la formule Business. Elles ont été gardées en sécurité et rien n'a été compté. Maintenant que la boutique est sur Business, vous pouvez les compter.",
