  "print.shippingNote": "Si la commande a une adresse de livraison, elle se remplit depuis la commande. Ce que vous tapez ici s’imprime une fois et n’est jamais enregistré.",
  "print.carrier.title": "Votre étiquette du transporteur",
  "print.carrier.desc": "Achetez l'affranchissement chez le transporteur, comme aujourd'hui — cette application ne vend jamais d'affranchissement, donc le prix que vous payez est toujours celui du transporteur. Enregistrez le fichier de l'étiquette ici et il reste sur cette commande pour de bon : votre archive, sous la main au cas où il arriverait quelque chose.",
