  "settings.businessCard.empty": "Aucune adresse ni aucun numéro de téléphone n’a encore été ajouté.",
  "staff.memberDialog.personalAddress": "Adresse du domicile",
  "staff.memberDialog.personalPhone": "Numéro de téléphone",
  "workforce.messages.voiceNote": "Note vocale",
