  "workforce.messages.sendVoice": "Envoyer la note vocale",
  "workforce.messages.discard": "La supprimer",
  "workforce.messages.micDenied": "Le microphone est bloqué, donc une note vocale ne peut pas être enregistrée. Vous pouvez autoriser le microphone dans les réglages de votre navigateur — ou simplement envoyer un message écrit à la place.",
  "workforce.messages.voiceFailed": "Cette note vocale n'a pas pu être envoyée. Veuillez réessayer.",
  "workforce.messages.sentLabel": "Envoyé",
  "workforce.messages.receivedLabel": "Reçu",
  "workforce.messages.readLabel": "Lu",
  "apiErrors.notFound.voiceNoteFound": "Note vocale introuvable.",
  "apiErrors.invalidValue.sendVoiceRecording": "Envoyez un enregistrement vocal de quelques minutes au maximum.",
  "apiErrors.invalidValue.recordingNotPrepared": "Cet enregistrement n’a pas pu être préparé — veuillez l’enregistrer à nouveau.",
  "training.lessons.messages-private.step5": "Vous pouvez aussi envoyer une note vocale : touchez le microphone à côté de la zone de message, parlez, puis touchez arrêter. Écoutez-la d’abord — puis envoyez-la, ou supprimez-la et réenregistrez. Quand quelqu’un vous en envoie une, touchez lecture pour entendre sa vraie voix.",
  "training.lessons.owner-messages-oversight.step5": "Marques de lecture : quand un membre de l’équipe lit un message que vous lui avez envoyé, vous le voyez marqué comme lu. Le personnel et les gestionnaires voient les marques de lecture les uns des autres de la même façon, dans les deux sens.",
  "training.lessons.owner-messages-oversight.step6": "Votre propre lecture est invisible. Quand vous lisez un message qu’un membre du personnel vous a envoyé, cette personne ne voit jamais de marque de lecture — et vous n’avez pas à dire à votre équipe que leurs conversations sont conservées dans l’application et que vous, le propriétaire, pouvez les lire. Cette surveillance fait partie de veiller sur votre magasin.",
  "training.lessons.owner-messages-oversight.step7": "Ce que vous faites des messages négatifs entre membres du personnel ne regarde que vous. Laissez passer, parlez discrètement à quelqu’un ou agissez — le choix vous appartient, et vous n’avez jamais à dire où vous l’avez vu.",
  "staffLib.perm.returnsComplete": "Terminer les remboursements et les échanges",
  "staffLib.area.returnsAccess": "Approbation des retours",
  "staff.memberDialog.returnsAccessHint": "Avec cette case cochée, cette personne peut approuver un retour et terminer le remboursement ou l’échange. Sans elle, un retour qu’elle commence attend le propriétaire ou un membre de l’équipe approuvé.",
