  "settings.platformPolicies.title": "Politiques de Luminous StockHaven",
  "settings.platformPolicies.description": "Les conditions et politiques propres à l’application. Elles restent avec l’application, et toute l’équipe peut les lire ici.",
  "staffWelcome.policiesIntro": "Avant de commencer : les politiques et conditions de votre magasin, écrites par le propriétaire.",
  "plansLib.includes.storePolicies": "Vos propres politiques et conditions de magasin dans Paramètres, à lire par toute votre équipe",
  "apiErrors.businessPoliciesOwnerOnly": "Seul le propriétaire peut modifier les politiques et conditions de ce magasin.",
  "apiErrors.policyFileInvalid": "Envoyez un fichier PDF, texte, Word ou OpenDocument de moins de 25 Mo.",
  "apiErrors.policyTextTooLong": "Ce document est trop long pour être tapé ici. Vous pouvez plutôt le téléverser comme fichier.",
  "training.lessons.owner-store-policies.title": "Les politiques et conditions de votre magasin",
  "training.lessons.owner-store-policies.step1": "Ouvrez Paramètres pour trouver la carte Politiques et conditions de votre magasin. Elle contient deux documents : les Politiques de votre magasin — les règles de la maison — et vos Conditions générales.",
  "training.lessons.owner-store-policies.step2": "Chaque document peut être tapé sur place, ou téléversé comme fichier (PDF, texte, Word ou OpenDocument, jusqu’à 25 Mo). C’est l’un ou l’autre : enregistrer le texte remplace un fichier, et téléverser un fichier remplace le texte. Retirer un document l’efface.",
  "training.lessons.owner-store-policies.step3": "Votre équipe voit les deux documents une fois, sur sa page de bienvenue à son arrivée, et peut les lire à tout moment dans ses Paramètres. Pour votre équipe, ils sont en lecture seule — vous seul pouvez les écrire ou les modifier.",
  "training.lessons.owner-store-policies.step4": "Chaque entreprise garde ses propres documents : ce que vous écrivez ici appartient à ce magasin seul et n’apparaît jamais dans une autre entreprise. Les conditions et politiques propres à Luminous StockHaven vivent à côté des vôtres dans Paramètres, et tout le monde peut les lire aussi.",
  "training.lessons.welcome-basics.step5": "Les politiques et conditions de votre magasin sont montrées une fois sur votre page de bienvenue, et elles vivent dans Paramètres, où vous pouvez les lire à tout moment.",
  "apiErrors.policyDocNotFound": "Ce document n'est pas l'un des deux.",
  "apiErrors.policyFileNotFound": "Aucun fichier n'est enregistré pour ce document.",
