  "staffLib.area.lowStockAccess": "Stock faible",
  "staff.memberDialog.lowStockAccessHint": "Avec la première coche, cette personne voit les alertes de stock faible — le cadre À surveiller, la page Stock faible et les marques de niveau bas. Avec la deuxième coche, elle peut modifier le seuil de réapprovisionnement d’un produit ; sans elle, le champ du seuil reste visible, mais une modification ne sera pas enregistrée.",
