  "staff.memberDialog.trainingAccessHint": "La lecture des politiques de la boutique et des conditions est pour tout le monde. Ces cases attribuent les formations avec quiz que le propriétaire crée à côté de chaque document dans Paramètres.",
  "staffLib.area.trainingAccess": "Formations avec quiz sur les politiques",
