  "plansLib.businessIncludes.xstoreMessages": "Messages inter-magasins — toute votre équipe, dans toutes vos entreprises",
  "xstore.title": "Messages inter-magasins",
  "xstore.help": "Toutes les personnes de ce compte, dans toutes vos entreprises, dans une seule boîte de réception. Écrivez à n'importe laquelle d'entre elles ici — par texte ou par message vocal, avec les mentions de distribution et de lecture. Vos Messages en magasin restent tels qu'ils sont.",
  "xstore.empty": "Aucune conversation pour le moment. Démarrez-en une avec Nouveau message.",
  "xstore.noPeople": "Il n'y a encore personne d'autre à qui écrire. Les personnes apparaissent ici dès qu'elles rejoignent l'une de vos entreprises et se connectent.",
  "xstore.deliveredLabel": "Distribué",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Les messages inter-magasins font partie de l'offre Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Cette personne ne fait pas partie de ce compte.",
  "training.lessons.owner-xstore-messages.title": "Des messages entre vos magasins, pour les propriétaires",
  "training.lessons.owner-xstore-messages.step1": "Les messages inter-magasins sont une deuxième boîte de réception, distincte de Messages. Messages concerne le magasin où vous vous trouvez ; cette porte vous permet de joindre toutes les personnes de votre compte, dans chaque entreprise que vous possédez — jusqu'à cinq.",
  "training.lessons.owner-xstore-messages.step2": "Ouvrez Messages inter-magasins depuis le menu et démarrez une conversation avec n'importe quelle personne de la liste. La liste affiche chaque membre de l'équipe, dans toutes vos entreprises, qui s'est connecté, avec les magasins où il travaille.",
  "training.lessons.owner-xstore-messages.step3": "Les photos accompagnent les noms : chaque personne affiche sa photo de profil approuvée, ou ses initiales si elle n'en a pas. Chaque message indique la date et l'heure de son envoi.",
  "training.lessons.owner-xstore-messages.step4": "Sous vos propres messages, vous pouvez voir Distribué dès qu'un message arrive, et Lu dès que l'autre personne ouvre la conversation. Les notes vocales fonctionnent aussi ici, exactement comme dans Messages.",
  "training.lessons.owner-xstore-messages.step5": "Les conversations ici sont privées entre les deux personnes qui y participent. Votre supervision des Messages en magasin ne s'étend pas d'un magasin à l'autre.",
  "training.lessons.mgr-xstore-messages.title": "Des messages entre vos magasins, pour les responsables",
  "training.lessons.mgr-xstore-messages.step1": "Les messages inter-magasins permettent de joindre toutes les personnes de ce compte, dans toutes les entreprises — pas seulement le magasin où vous vous trouvez. Ils se trouvent dans le menu, séparés de Messages.",
  "training.lessons.mgr-xstore-messages.step2": "Démarrez une conversation depuis la liste : chaque membre de l'équipe qui s'est connecté y figure, avec les magasins où il travaille à côté de son nom.",
  "training.lessons.mgr-xstore-messages.step3": "Envoyez un texte, ou enregistrez une note vocale. Avant l'envoi d'une note vocale, vous pouvez la réécouter, la supprimer ou l'envoyer — comme dans Messages.",
  "training.lessons.mgr-xstore-messages.step4": "Vos messages affichent Distribué quand ils arrivent et Lu quand l'autre personne ouvre la conversation. La photo à côté de chaque nom est la photo de profil approuvée de cette personne.",
  "training.lessons.staff-xstore-messages.title": "Des messages entre vos magasins",
  "training.lessons.staff-xstore-messages.step1": "Les messages inter-magasins vous permettent de joindre n'importe quelle personne de ce compte, dans n'importe quelle entreprise du propriétaire — une question pour un autre magasin n'a plus à attendre.",
  "training.lessons.staff-xstore-messages.step2": "Ouvrez-les depuis le menu, choisissez la personne et écrivez. Si la personne qu'il vous faut n'est pas dans la liste, elle ne s'est pas encore connectée — elle apparaîtra dès qu'elle le fera.",
  "training.lessons.staff-xstore-messages.step3": "Vous pouvez aussi envoyer des notes vocales ici : enregistrez, réécoutez, puis envoyez ou supprimez. Chaque message affiche la date et l'heure de son envoi.",
  "training.lessons.staff-xstore-messages.step4": "Quand vous envoyez un message, il affiche Distribué dès qu'il arrive, et Lu dès que l'autre personne ouvre la conversation. Une conversation est privée entre vous et l'autre personne.",
