  "storefronts.ebayDesc": "Connectez votre boutique eBay une seule fois. Quand un article se vend sur eBay, son nombre diminue ici tout seul, et la vente est enregistrée dans vos mouvements — comme s'il avait été scanné à la sortie. Les ventes ne circulent que dans un sens : d'eBay vers l'application.",
