  "training.lessons.owner-ebay-connect.step1": "Ouvrez Connexions aux boutiques (dans le groupe Ventes) et touchez Connecter eBay. Vous vous connectez sur la page d'eBay elle-même — l'application ne voit jamais votre mot de passe eBay.",
  "training.lessons.owner-ebay-connect.step2": "Une boutique eBay se connecte à une entreprise — l'entreprise dont cette boutique vend les articles. Si vous gérez plus d'une entreprise, connectez chaque boutique à sa propre entreprise.",
