  "training.lessons.owner-ebay-connect.step5": "Une vente est associée grâce au SKU, au UPC ou à l'ISBN — celui des trois que porte l'annonce. Si une vente ne peut pas être associée, elle attend sous « Ventes à associer » sur la page Connexions aux boutiques : associez-la une fois à son produit, et cette vente — ainsi que les futures ventes du même genre — s'enregistreront toutes seules. « Vérifier les ventes maintenant » récupère tout ce qui est récent, et Déconnecter arrête la connexion ; les ventes déjà enregistrées restent.",
